package dev.awaken.arms;

import org.jspecify.annotations.Nullable;

import java.util.List;

/**
 * Arms' third-person clips for players with the Player Animation Library (optional): generated by
 * tools/art/specs/arms_moves.py into {@code assets/awaken/player_animations/arms_moves.json} from the timing table's
 * rows, each with a {@code _bent} twin for Bendable Cuboids, and played through {@code core.api.PlayerClips} by the
 * client (arms.client.ArmsBodies). Without the library a fighter keeps vanilla's arm swing. Common so the GameTests
 * can hold these names to the file.
 */
public final class ArmsClips {
    private ArmsClips() {}

    public static final String FILE = "assets/awaken/player_animations/arms_moves.json";

    /** Held while they last (loops), each with an {@code _end} settle. */
    public static final String GUARD = "arms_guard", CHARGE = "arms_heavy_charge";
    public static final String DODGE_BACK = "arms_dodge_back", DODGE_LEFT = "arms_dodge_left", DODGE_RIGHT = "arms_dodge_right";

    public static final List<String> ALL = List.of("arms_strike_1", "arms_strike_2", "arms_strike_3", "arms_strike_4", "arms_heavy",
            "arms_riposte", "arms_slipcut", "arms_execution", "arms_art", "arms_undercut", "arms_plunge", GUARD, GUARD + "_end", CHARGE, CHARGE + "_end", DODGE_BACK, DODGE_LEFT, DODGE_RIGHT);

    /**
     * Styles with their own slide, fall and dodge moves (arms_<style>_<move>): the Gauntlets punch them (before, every
     * style played the Longsword's sword sweeps there, so the fists' own never showed), and the styles third person
     * takes from first person's blade (tools/art/specs/arms_rig4.py: both hands on the hilt) swing them as they swing
     * the rest. Every other shares the Longsword's.
     */
    public static final java.util.Set<String> OWN_SHARED = java.util.Set.of("gauntlets", "katana", "greatblade", "maul", "spear",
            "glaive", "scythe", "warstaff", "twinblades");

    /** Styles that hold their own heavy's draw while it charges (arms_<style>_heavy_charge: the very pose it is loosed from). */
    public static final java.util.Set<String> OWN_CHARGE = java.util.Set.of("katana", "greatblade", "maul", "spear", "glaive",
            "scythe", "warstaff", "twinblades");

    /** The held draw a style charges in. */
    public static String charge(String style) {
        return OWN_CHARGE.contains(style) ? "arms_" + style + "_heavy_charge" : CHARGE;
    }

    /**
     * The clip a move plays for a style: the style's own on its own row's ticks (arms_<style>_<move>, generated for
     * every move; the slide's, the fall's and the dodge's only for {@link #OWN_SHARED}), else the Longsword's.
     */
    public static @Nullable String of(String style, Archetype.Move move) {
        boolean shared = move == Archetype.Move.UNDERCUT || move == Archetype.Move.PLUNGE || move == Archetype.Move.SLIPCUT;
        if (style.equals(Arms.LONGSWORD) || shared && !OWN_SHARED.contains(style)) {
            return of(move);
        }
        return "arms_" + style + "_" + move.key;
    }

    /** The Longsword's clip for a move (a fifth strike borrows the first's), or null for one without its own. */
    public static @Nullable String of(Archetype.Move move) {
        return switch (move) {
            case STRIKE_1, STRIKE_2, STRIKE_3, STRIKE_4 -> "arms_" + move.key;
            case STRIKE_5 -> "arms_strike_1";
            case HEAVY, RIPOSTE, SLIPCUT, EXECUTION, ART, UNDERCUT, PLUNGE -> "arms_" + move.key;
        };
    }

    public static boolean loops(String clip) {
        return clip.equals(GUARD) || clip.endsWith("heavy_charge");
    }

    /** The dodge's clip for a way relative to where the body faces (degrees, 0 ahead, + toward the main hand). */
    public static String dodge(float relativeYaw) {
        float a = Math.abs(relativeYaw);
        if (a >= 120) return DODGE_BACK;
        return relativeYaw > 0 ? DODGE_RIGHT : DODGE_LEFT;
    }
}
